mapper.select:
select distinct taskcomment, storeroomno, data2, data3, forcesite, forcebatch, intaskno, indesc, workstation, intaskid, indate, PARNAME from
( SELECT taskcomment, storeroomno, data2, data3, forcesite, forcebatch, intaskno, indesc, workstation, storeroomname, operation, userid, instate, data1, collecter, i_collecter, t_collecter, roomtag, intaskid, transfertype, indate, PARNAME
FROM ( SELECT pm.matcode, pm.matname, sts.Storesiteno, ii.qty, NVL(ii.collectedqty,0) as collectedqty, ii.batchno, NVL(i.indesc,' ') AS indesc, ii.sn, str.storeroomno AS storeroomno, ibl.subinventory_code, i.forcesite, i.forcebatch, NVL(i.data2,' ') as data2, NVL(i.data3,' ') as data3, i.intaskno, i.taskcomment, NVL(ibl.workstation,'N') AS workstation, ibl.palletno, i.data1, ii.intaskitemid, ii.intaskitemid AS ID, ii.intaskid, ii.materialid, ii.inbillid, str.storeroomname, str.roomtag, e.operation, e.userid, NVL(ii.instate,0) AS instate, NVL(i.collecter,0) AS collecter, NVL(ii.collecter,0) AS i_collecter, NVL(i.collecter,0) AS t_collecter, i.indate, p.parno, NVL(inf.transfertype,'0') transfertype, inf.proofno, inf.protype, p.PARNAME
FROM deliverytask i, deliverytaskitem ii, pm_material pm, storeroom str, storesite sts, deliveryproof inf, deliverybill ibl, (select distinct r.USER_ID as userid,m.STOREROOMID as operation from sys_user_role r,sys_role_room m where r.ROLE_ID=m.ROLE_ID) e, partner p WHERE i.intaskid=ii.intaskid AND ii.materialid = pm.pm_materialid AND i.storeroomid = str.storeroomid AND ii.hintedsite = sts.storesiteid(+) AND inf.inproofid = i.tasksource AND ibl.inproofid = inf.inproofid AND inf.partnerid = p.partnerid(+) AND ibl.materialid = pm.pm_materialid AND ibl.inbillid = ii.inbillid AND str.storeroomid = e.operation AND (NVL(ii.qty,0)-NVL(ii.collectedqty,0)) > 0 and nvl(ii.collecter,0) = #{i_collecter}
and nvl(ii.instate,0) = #{instate}
and nvl(ii.instate,0) >=1
and nvl(e.userid,0) = #{userId} and nvl(inf.transfertype,0) = #{transferType} ) GROUP BY taskcomment, storeroomno, storeroomname, data1, data2, data3, forcesite, forcebatch, intaskid, intaskno, workstation, transfertype, indesc, operation, userid, instate, collecter, i_collecter, t_collecter, roomtag, indate, PARNAME)d1 where 1=1
and( d1.taskcomment like concat(concat('%',#{searchKey}),'%') or d1.intaskno like concat(concat('%',#{searchKey}),'%') or d1.data2 like concat(concat('%',#{searchKey}),'%') )
order by d1.indate desc,d1.taskcomment desc, d1.intaskno desc order by d1.${sortColumn} ${sortType}

select distinct taskcomment, storeroomno, data2, data3, forcesite, forcebatch, intaskno, indesc, workstation, intaskid, indate, PARNAME from
( SELECT taskcomment, storeroomno, data2, data3, forcesite, forcebatch, intaskno, indesc, workstation, storeroomname, operation, userid, instate, data1, collecter, i_collecter, t_collecter, roomtag, intaskid, transfertype, indate, PARNAME
FROM ( SELECT pm.matcode, pm.matname, sts.Storesiteno, ii.qty, NVL(ii.collectedqty,0) as collectedqty, ii.batchno, NVL(i.indesc,' ') AS indesc, ii.sn, str.storeroomno AS storeroomno, ibl.subinventory_code, i.forcesite, i.forcebatch, NVL(i.data2,' ') as data2, NVL(i.data3,' ') as data3, i.intaskno, i.taskcomment, NVL(ibl.workstation,'N') AS workstation, ibl.palletno, i.data1, ii.intaskitemid, ii.intaskitemid AS ID, ii.intaskid, ii.materialid, ii.inbillid, str.storeroomname, str.roomtag, e.operation, e.userid, NVL(ii.instate,0) AS instate, NVL(i.collecter,0) AS collecter, NVL(ii.collecter,0) AS i_collecter, NVL(i.collecter,0) AS t_collecter, i.indate, p.parno, NVL(inf.transfertype,'0') transfertype, inf.proofno, inf.protype, p.PARNAME
FROM deliverytask i, deliverytaskitem ii, pm_material pm, storeroom str, storesite sts, deliveryproof inf, deliverybill ibl, (select distinct r.USER_ID as userid,m.STOREROOMID as operation from sys_user_role r,sys_role_room m where r.ROLE_ID=m.ROLE_ID) e, partner p WHERE i.intaskid=ii.intaskid AND ii.materialid = pm.pm_materialid AND i.storeroomid = str.storeroomid AND ii.hintedsite = sts.storesiteid(+) AND inf.inproofid = i.tasksource AND ibl.inproofid = inf.inproofid AND inf.partnerid = p.partnerid(+) AND ibl.materialid = pm.pm_materialid AND ibl.inbillid = ii.inbillid AND str.storeroomid = e.operation and nvl(ii.collecter,0) = #{i_collecter}
and nvl(ii.instate,0) = #{instate}
and nvl(ii.instate,0) >=1
and nvl(e.userid,0) = #{userId} and nvl(inf.transfertype,0) = #{transferType} ) GROUP BY taskcomment, storeroomno, storeroomname, data1, data2, data3, forcesite, forcebatch, intaskid, intaskno, workstation, transfertype, indesc, operation, userid, instate, collecter, i_collecter, t_collecter, roomtag, indate, PARNAME)d1 where 1=1
and( d1.taskcomment like concat(concat('%',#{searchKey}),'%') or d1.intaskno like concat(concat('%',#{searchKey}),'%') or d1.data2 like concat(concat('%',#{searchKey}),'%') )
order by d1.indate desc,d1.taskcomment desc, d1.intaskno desc order by d1.${sortColumn} ${sortType}

mapper.update:
update intask
intaskno = #{intaskno}, tasksource = #{tasksource}, taskcomment = #{taskcomment}, storeroomid = #{storeroomid}, collecter = #{collecter}, instate = #{instate}, collectkind = #{collectkind}, indate = #{indate}, indesc = #{indesc}, dataversion = #{dataversion}, data1 = #{data1}, data2 = #{data2}, data3 = #{data3}, data4 = #{data4}, data5 = #{data5}, data6 = #{data6}, data7 = #{data7}, data8 = #{data8}, forcesite = #{forcesite}, forcebatch = #{forcebatch}, batchflag = #{batchflag},
where intaskid = #{intaskid}
